// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address owner, address addr1, address addr2, uint256 val1, uint256 val2) public {
        vm.assume(owner != address(0) && addr1 != address(0) && addr2 != address(0));
        vm.assume(owner != addr1 && owner != addr2 && addr1 != addr2);
        val1 = bound(val1, 0, c.totalRemaining());
        val2 = bound(val2, 0, c.totalRemaining());

        vm.prank(owner);
        c.NETM();

        // Distribute some tokens to addr1 and addr2 to accumulate balances
        vm.prank(owner);
        c.finishDistribution();
        // Re-enable distribution is not possible, so we skip that; instead we directly simulate transfers
        // To have balances for invariant check, we transfer to addr1 and addr2 using the owner's tokens
        // Note: Distr is private, so we use transfer after ensuring owner has tokens
        if(c.balanceOf(owner) >= val1) {
            vm.prank(owner);
            c.transfer(addr1, val1);
        }
        if(c.balanceOf(owner) >= val2) {
            vm.prank(owner);
            c.transfer(addr2, val2);
        }

        // Compute sum of balances for the three addresses
        uint256 sum = c.balanceOf(owner) + c.balanceOf(addr1) + c.balanceOf(addr2);
        // Invariant: totalDistributed equals sum of all balances (since no other balances exist)
        assertTrue(sum == c.totalDistributed());
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address ownerAddr) public {
        vm.assume(ownerAddr != address(0) && ownerAddr != address(this));
        vm.prank(c.owner());
        c.transferOwnership(ownerAddr);
        vm.prank(ownerAddr);
        c.NETM();
        uint256 supply = c.totalSupply();
        uint256 remaining = c.totalRemaining();
        uint256 distributed = c.totalDistributed();
        assertTrue(supply - remaining == distributed);
    }
}

