pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address owner, address other) public {
        vm.assume(owner != address(0));
        vm.assume(other != address(0));
        vm.assume(owner != other);
        vm.prank(owner);
        c.NETM();
        uint256 sumBalances = c.balanceOf(owner) + c.balanceOf(other);
        assertTrue(sumBalances == c.totalSupply());
    }
}
